read_queries:
select jsonb_build_object(
'observed_at',now(),
'tables',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default) order by table_name,ordinal_position) from information_schema.columns where table_schema='public' and table_name in ('places','bands','agents','image_authorships','image_steps','outing_music_positions','outing_music_assignments','brotherhood_images','brotherhood_steps','entity_locations','heritage_assets','sources','source_links','outings','image_interventions','step_interventions')),
'checks',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid))) from pg_constraint where connamespace='public'::regnamespace and contype in ('c','u','f') and conrelid in (select c.oid from pg_class c where c.relnamespace='public'::regnamespace and c.relname in ('places','bands','agents','image_authorships','image_steps','outing_music_positions','outing_music_assignments','brotherhood_images','brotherhood_steps','entity_locations','heritage_assets','sources','source_links','outings'))),
'namespace_collisions',(select count(*) from public.entities where id::text >= 'c0160038-' and id::text < 'c0160039-')
) as data;
